using Microsoft.EntityFrameworkCore;

/// <summary>
/// Cosmos DB context demonstrating EF Core 9 breaking change mitigations
/// for existing documents that use the old "Discriminator" property and
/// the old compound id format (e.g. "Product|123").
/// </summary>
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: Default discriminator property renamed from
        // "Discriminator" to "$type" in EF Core 9.
        // Fix: Explicitly set "Discriminator" to match existing documents.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // Breaking change: id property no longer embeds the discriminator
        // (e.g. stored as "123" instead of "Product|123").
        // Fix: Preserve old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class Product
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
    public decimal Price { get; set; }
}

using Microsoft.EntityFrameworkCore;

/// <summary>
/// Demonstrates the sync I/O breaking change fix for EF Core 9 Cosmos DB provider.
/// Synchronous methods (ToList, SaveChanges, etc.) now throw — use async equivalents.
/// </summary>
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Breaking change: Sync I/O is no longer supported on the Cosmos DB provider.
    // ToList(), First(), SaveChanges(), etc. now throw at runtime.
    // Fix: Use async equivalents (ToListAsync, FirstAsync, SaveChangesAsync).

    public async Task<List<Product>> GetProductsAsync()
    {
        return await _db.Products.ToListAsync();
    }

    public async Task<Product?> GetProductAsync(string id)
    {
        return await _db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }

    public async Task AddProductAsync(Product product)
    {
        _db.Products.Add(product);
        await _db.SaveChangesAsync();
    }
}

